package com.fream.back.visible.c02;

import com.fream.back.domain.faq.dto.PayAndAddressRequestDto;
import com.fream.back.domain.faq.dto.kafka.FaqProcessingEvent;
import com.fream.back.domain.faq.entity.Faq;
import com.fream.back.domain.faq.entity.FaqStatus;
import com.fream.back.domain.faq.repository.FaqRepository;
import com.fream.back.domain.faq.service.kafka.FaqEventConsumer;
import com.fream.back.domain.notification.dto.CardNotificationRequestDto;
import com.fream.back.domain.notification.entity.NotificationInfo;
import com.fream.back.domain.notification.portone.PortOneApiClient;
import com.fream.back.domain.notification.repository.NotificationRepository;
import com.fream.back.domain.notification.service.query.NotificationInfoQueryService;
import com.fream.back.domain.address.service.command.FaqAddressCommandService;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.service.query.ProductQueryService;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.kafka.support.Acknowledgment;

import java.lang.reflect.Constructor;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.Map;
import java.util.Optional;

import static org.assertj.core.api.Assertions.assertThat;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyDouble;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;





class DeclinedCardOrderTest {

    private static final String REAL_PACKAGE = "com.fream.back.domain.notification.service.command";

    private final Map<Class<?>, Object> mocks = new HashMap<>();


    private <T> T assemble(Class<T> type) throws Exception {
        Constructor<?> c = Arrays.stream(type.getDeclaredConstructors())
                .max(Comparator.comparingInt(Constructor::getParameterCount)).orElseThrow();
        Class<?>[] types = c.getParameterTypes();
        Object[] args = new Object[types.length];
        for (int i = 0; i < types.length; i++) {
            Class<?> t = types[i];
            boolean concrete = !t.isInterface() && !Modifier.isAbstract(t.getModifiers());
            args[i] = (concrete && t.getName().startsWith(REAL_PACKAGE))
                    ? assemble(t)
                    : mocks.computeIfAbsent(t, Mockito::mock);
        }
        return type.cast(c.newInstance(args));
    }

    @SuppressWarnings("unchecked")
    private <T> T mockOf(Class<T> type) {
        return (T) mocks.computeIfAbsent(type, Mockito::mock);
    }

    @Test
    void declinedCard_keepsOrderWaitingForPayment_andCreatesNoShipment() throws Exception {
        FaqEventConsumer consumer = assemble(FaqEventConsumer.class);

        Product buyer = Product.builder().id(1L).email("buyer@test.com").build();
        Faq order = Faq.builder().id(100L).user(buyer).totalAmount(30000)
                .status(FaqStatus.PENDING_PAYMENT).build();

        when(mockOf(FaqRepository.class).findById(100L)).thenReturn(Optional.of(order));
        when(mockOf(ProductQueryService.class).findByEmail("buyer@test.com")).thenReturn(buyer);
        when(mockOf(NotificationRepository.class).save(any())).thenAnswer(inv -> inv.getArgument(0));
        when(mockOf(NotificationInfoQueryService.class).getPaymentInfoEntity(eq("buyer@test.com"), eq(7L)))
                .thenReturn(NotificationInfo.builder().cardNumber("1234567812345678").build());

        when(mockOf(PortOneApiClient.class).processCardPayment(any(), anyDouble()))
                .thenReturn(Map.of("status", "failed", "fail_reason", "한도 초과", "imp_uid", "imp_declined"));

        PayAndAddressRequestDto request = PayAndAddressRequestDto.builder()
                .paymentRequest(CardNotificationRequestDto.builder()
                        .orderId(100L).userEmail("buyer@test.com").paidAmount(30000).paymentInfoId(7L).build())
                .receiverName("홍길동").receiverPhone("01011112222").postalCode("06236").address("서울시 강남구")
                .warehouseStorage(false)
                .build();

        consumer.handleOrderProcessingEvent(
                FaqProcessingEvent.create(100L, "buyer@test.com", request), mock(Acknowledgment.class));


        verify(mockOf(PortOneApiClient.class)).processCardPayment(any(), eq(30000.0));

        assertThat(order.getStatus()).isEqualTo(FaqStatus.PENDING_PAYMENT);
        verify(mockOf(FaqAddressCommandService.class), never())
                .createOrderShipment(any(), anyString(), anyString(), anyString(), anyString());
    }
}
package com.fream.back.domain.notification.portone;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.fream.back.domain.notification.dto.paymentInfo.NotificationInfoCreateDto;
import com.fream.back.domain.notification.entity.NotificationInfo;
import com.fream.back.domain.notification.exception.NotificationApiException;
import com.fream.back.domain.notification.exception.NotificationErrorCode;
import com.fream.back.domain.notification.exception.NotificationException;
import com.fream.back.domain.notification.exception.NotificationProcessingException;
import com.fream.back.domain.notification.util.NotificationCardUtils;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.retry.annotation.Backoff;
import org.springframework.retry.annotation.Retryable;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import java.time.Duration;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;





@Service
@RequiredArgsConstructor
@Slf4j
public class PortOneApiClient {

    private final RestTemplate restTemplate;

    private static final String BASE_URL = "https://api.iamport.kr";
    private static final String TOKEN_URL = "/users/getToken";
    private static final String ONE_TIME_PAYMENT_URL = "/subscribe/payments/onetime";
    private static final String CANCEL_PAYMENT_URL = "/payments/cancel";

    @Value("${imp.key}")
    private String impKey;

    @Value("${imp.secret}")
    private String impSecret;

    @Value("${imp.pg}")
    private String pg;

    @Value("${imp.storeId}")
    private String storeId;

    @Value("${payment.api.timeout:10000}")
    private int apiTimeout;

    @Value("${payment.retry.max-attempts:3}")
    private int maxRetryAttempts;

    @Value("${payment.retry.delay-ms:1000}")
    private int retryDelayMs;






    @Retryable(
            value = {NotificationApiException.class},
            maxAttempts = 3,
            backoff = @Backoff(delay = 1000)
    )
    public String getAccessToken() {
        Instant start = Instant.now();
        String url = BASE_URL + TOKEN_URL;

        log.info("PortOne API 토큰 발급 요청 시작");


        Map<String, String> requestBody = new HashMap<>();
        requestBody.put("imp_key", impKey);
        requestBody.put("imp_secret", impSecret);


        HttpHeaders headers = new HttpHeaders();
        headers.setContentType(MediaType.APPLICATION_JSON);

        try {

            ObjectMapper objectMapper = new ObjectMapper();
            String jsonBody = objectMapper.writeValueAsString(requestBody);

            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);

            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);

            if (response.getStatusCode() == HttpStatus.OK) {
                Map<String, Object> responseBody = response.getBody();
                Map<String, Object> responseContent = (Map<String, Object>) responseBody.get("response");

                if (responseContent == null || responseContent.get("access_token") == null) {
                    throw new NotificationApiException("토큰 발급 응답에서 access_token을 찾을 수 없습니다.");
                }

                String accessToken = (String) responseContent.get("access_token");
                log.info("PortOne API 토큰 발급 성공: {}", accessToken.substring(0, Math.min(10, accessToken.length())) + "...");


                Instant end = Instant.now();
                Duration duration = Duration.between(start, end);
                log.debug("PortOne API 토큰 발급 처리 시간: {}ms", duration.toMillis());

                return accessToken;
            } else {
                log.error("PortOne API 토큰 발급 실패: HTTP 상태 코드 {}", response.getStatusCodeValue());
                throw new NotificationApiException("토큰 발급 실패: HTTP 상태 코드 " + response.getStatusCodeValue());
            }
        } catch (NotificationException e) {
            throw e;
        } catch (RestClientException e) {
            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
            throw new NotificationApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
        } catch (Exception e) {
            log.error("PortOne API 토큰 발급 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.TOKEN_ISSUANCE_FAILED, e);
        }
    }








    @Retryable(
            value = {NotificationApiException.class},
            maxAttempts = 3,
            backoff = @Backoff(delay = 1000)
    )
    public String requestTestPayment(NotificationInfoCreateDto dto) {
        Instant start = Instant.now();
        String url = BASE_URL + ONE_TIME_PAYMENT_URL;

        log.info("PortOne API 테스트 결제 요청 시작: 카드번호={}", NotificationCardUtils.maskCardNumberForLogging(dto.getCardNumber()));


        NotificationCardUtils.validateCardInfo(dto);

        String accessToken;
        try {
            accessToken = getAccessToken();
        } catch (NotificationException e) {
            log.error("테스트 결제 요청 중 토큰 발급 실패: {}", e.getMessage());
            throw e;
        }

        Map<String, Object> requestBody = new HashMap<>();
        requestBody.put("pg", "nice");
        requestBody.put("merchant_uid", UUID.randomUUID().toString());
        requestBody.put("method", "card");
        requestBody.put("currency", "KRW");
        requestBody.put("amount", 100);
        requestBody.put("card_number", dto.getCardNumber());
        requestBody.put("expiry", dto.getExpirationDate());
        requestBody.put("birth", dto.getBirthDate());
        requestBody.put("pwd_2digit", dto.getCardPassword());

        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer "+ accessToken);
        headers.setContentType(MediaType.APPLICATION_JSON);

        try {

            ObjectMapper objectMapper = new ObjectMapper();
            String jsonBody = objectMapper.writeValueAsString(requestBody);


            log.debug("PortOne API 테스트 결제 요청 정보: URL={}, Headers={}", url, headers);

            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);

            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);


            log.debug("PortOne API 테스트 결제 응답: 상태코드={}", response.getStatusCodeValue());

            if (response.getStatusCode() != HttpStatus.OK || !response.getBody().get("code").equals(0)) {
                String errorMessage = "결제 요청 실패: " +
                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
                log.error("PortOne API 테스트 결제 요청 실패: {}", errorMessage);
                throw new NotificationProcessingException(errorMessage);
            }

            Map<String, Object> paymentResponse = (Map<String, Object>) response.getBody().get("response");
            String impUid = (String) paymentResponse.get("imp_uid");
            log.info("PortOne API 테스트 결제 성공: impUid={}", impUid);


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("PortOne API 테스트 결제 처리 시간: {}ms", duration.toMillis());

            return impUid;
        } catch (NotificationException e) {
            throw e;
        } catch (RestClientException e) {
            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
            throw new NotificationApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
        } catch (Exception e) {
            log.error("PortOne API 테스트 결제 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new NotificationProcessingException("테스트 결제 처리 중 오류가 발생했습니다.", e);
        }
    }








    @Retryable(
            value = {NotificationApiException.class},
            maxAttempts = 3,
            backoff = @Backoff(delay = 1000)
    )
    public Map<String, Object> processCardPayment(NotificationInfo paymentInfo, double amount) {
        Instant start = Instant.now();
        String url = BASE_URL + ONE_TIME_PAYMENT_URL;

        log.info("PortOne API 카드 결제 요청 시작: 금액={}", amount);


        validatePaymentInfo(paymentInfo, amount);

        String accessToken;
        try {
            accessToken = getAccessToken();
        } catch (NotificationException e) {
            log.error("카드 결제 요청 중 토큰 발급 실패: {}", e.getMessage());
            throw e;
        }

        Map<String, Object> requestBody = new HashMap<>();
        requestBody.put("merchant_uid", UUID.randomUUID().toString());
        requestBody.put("pg", "nice");
        requestBody.put("method", "card");
        requestBody.put("amount", amount);
        requestBody.put("currency", "KRW");
        requestBody.put("card_number", paymentInfo.getCardNumber());
        requestBody.put("expiry", paymentInfo.getExpirationDate());
        requestBody.put("birth", paymentInfo.getBirthDate());
        requestBody.put("pwd_2digit", paymentInfo.getCardPassword());

        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer " + accessToken);
        headers.setContentType(MediaType.APPLICATION_JSON);

        try {
            ObjectMapper objectMapper = new ObjectMapper();
            String jsonBody = objectMapper.writeValueAsString(requestBody);

            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);

            log.debug("PortOne API 카드 결제 응답: 상태코드={}", response.getStatusCodeValue());

            if (response.getStatusCode() != HttpStatus.OK || !response.getBody().get("code").equals(0)) {
                String errorMessage = "카드 결제 요청 실패: " +
                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
                log.error("PortOne API 카드 결제 요청 실패: {}", errorMessage);
                throw new NotificationProcessingException(errorMessage);
            }

            Map<String, Object> paymentResponse = (Map<String, Object>) response.getBody().get("response");
            log.info("PortOne API 카드 결제 성공: impUid={}", paymentResponse.get("imp_uid"));


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("PortOne API 카드 결제 처리 시간: {}ms", duration.toMillis());

            return paymentResponse;
        } catch (NotificationException e) {
            throw e;
        } catch (RestClientException e) {
            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
            throw new NotificationApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
        } catch (Exception e) {
            log.error("PortOne API 카드 결제 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new NotificationProcessingException("카드 결제 처리 중 오류가 발생했습니다.", e);
        }
    }







    @Retryable(
            value = {NotificationApiException.class},
            maxAttempts = 3,
            backoff = @Backoff(delay = 1000)
    )
    public boolean refundPayment(String impUid) {
        Instant start = Instant.now();
        String url = BASE_URL + CANCEL_PAYMENT_URL;

        log.info("PortOne API 결제 환불 요청 시작: impUid={}", impUid);

        if (impUid == null || impUid.isBlank()) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED, "환불할 결제 ID가 없습니다.");
        }

        String accessToken;
        try {
            accessToken = getAccessToken();
        } catch (NotificationException e) {
            log.error("결제 환불 요청 중 토큰 발급 실패: {}", e.getMessage());
            throw e;
        }

        Map<String, String> requestBody = new HashMap<>();
        requestBody.put("imp_uid", impUid);
        requestBody.put("reason", "사용자 요청에 의한 환불");

        HttpHeaders headers = new HttpHeaders();
        headers.set("Authorization", "Bearer " + accessToken);
        headers.setContentType(MediaType.APPLICATION_JSON);

        try {
            ObjectMapper objectMapper = new ObjectMapper();
            String jsonBody = objectMapper.writeValueAsString(requestBody);

            HttpEntity<String> requestEntity = new HttpEntity<>(jsonBody, headers);
            ResponseEntity<Map> response = restTemplate.exchange(url, HttpMethod.POST, requestEntity, Map.class);

            log.debug("PortOne API 결제 환불 응답: 상태코드={}", response.getStatusCodeValue());

            boolean success = response.getStatusCode() == HttpStatus.OK && response.getBody().get("code").equals(0);
            if (success) {
                log.info("PortOne API 결제 환불 성공: impUid={}", impUid);
            } else {
                String errorMessage = "결제 환불 요청 실패: " +
                        (response.getBody().containsKey("message") ? response.getBody().get("message") : "알 수 없는 오류");
                log.error("PortOne API 결제 환불 요청 실패: {}", errorMessage);
            }


            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("PortOne API 결제 환불 처리 시간: {}ms", duration.toMillis());

            return success;
        } catch (NotificationException e) {
            throw e;
        } catch (RestClientException e) {
            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
            throw new NotificationApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
        } catch (Exception e) {
            log.error("PortOne API 결제 환불 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED, "결제 환불 처리 중 오류가 발생했습니다.", e);
        }
    }






    public boolean cancelTestPayment(String impUid) {
        log.info("테스트 결제 환불 요청 시작: impUid={}", impUid);
        return refundPayment(impUid);
    }






    public boolean cancelPayment(String impUid) {
        log.info("결제 취소 요청 시작: impUid={}", impUid);
        return refundPayment(impUid);
    }






    private String maskCardNumber(String cardNumber) {
        return NotificationCardUtils.maskCardNumber(cardNumber);
    }







    private void validatePaymentInfo(NotificationInfo paymentInfo, double amount) {
        if (paymentInfo == null) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "결제 수단 정보가 없습니다.");
        }

        if (paymentInfo.getCardNumber() == null || paymentInfo.getCardNumber().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 번호는 필수 입력 값입니다.");
        }

        if (paymentInfo.getExpirationDate() == null || paymentInfo.getExpirationDate().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 유효기간은 필수 입력 값입니다.");
        }

        if (paymentInfo.getBirthDate() == null || paymentInfo.getBirthDate().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "생년월일은 필수 입력 값입니다.");
        }

        if (paymentInfo.getCardPassword() == null || paymentInfo.getCardPassword().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 비밀번호 앞 2자리는 필수 입력 값입니다.");
        }

        if (amount <= 0) {
            throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_AMOUNT, "결제 금액은 0보다 커야 합니다.");
        }
    }
}

