            Instant end = Instant.now();
            Duration duration = Duration.between(start, end);
            log.debug("PortOne API 결제 환불 처리 시간: {}ms", duration.toMillis());

            return success;
        } catch (NotificationException e) {
            throw e;
        } catch (RestClientException e) {
            log.error("PortOne API 통신 중 오류 발생: {}", e.getMessage(), e);
            throw new NotificationApiException("결제 서비스 API 통신 중 오류가 발생했습니다.", e);
        } catch (Exception e) {
            log.error("PortOne API 결제 환불 요청 중 예상치 못한 오류 발생: {}", e.getMessage(), e);
            throw new NotificationException(NotificationErrorCode.PAYMENT_CANCELLATION_FAILED, "결제 환불 처리 중 오류가 발생했습니다.", e);
        }
