    public boolean cancelPayment(String impUid) {
        log.info("결제 취소 요청 시작: impUid={}", impUid);
        return refundPayment(impUid);
    }






    private String maskCardNumber(String cardNumber) {
        return NotificationCardUtils.maskCardNumber(cardNumber);
    }







    private void validatePaymentInfo(NotificationInfo paymentInfo, double amount) {
        if (paymentInfo == null) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "결제 수단 정보가 없습니다.");
        }

        if (paymentInfo.getCardNumber() == null || paymentInfo.getCardNumber().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 번호는 필수 입력 값입니다.");
        }

        if (paymentInfo.getExpirationDate() == null || paymentInfo.getExpirationDate().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 유효기간은 필수 입력 값입니다.");
        }

        if (paymentInfo.getBirthDate() == null || paymentInfo.getBirthDate().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "생년월일은 필수 입력 값입니다.");
        }

        if (paymentInfo.getCardPassword() == null || paymentInfo.getCardPassword().isBlank()) {
            throw new NotificationException(NotificationErrorCode.INVALID_CARD_INFO, "카드 비밀번호 앞 2자리는 필수 입력 값입니다.");
        }

        if (amount <= 0) {
            throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_AMOUNT, "결제 금액은 0보다 커야 합니다.");
        }
    }
}

