    private void validatePaymentRequest(Faq order, Product user, NotificationRequestDto requestDto) {
        if (order == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "주문 정보가 없습니다.");
        }

        if (user == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_PROCESSING_FAILED, "사용자 정보가 없습니다.");
        }

        if (requestDto == null) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED, "결제 요청 정보가 없습니다.");
        }


        if (!order.getId().equals(requestDto.getOrderId())) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                    "주문 ID가 일치하지 않습니다. 요청ID: " + requestDto.getOrderId() + ", 실제ID: " + order.getId());
        }

        if (!user.getEmail().equals(requestDto.getUserEmail())) {
            throw new NotificationException(NotificationErrorCode.PAYMENT_VALIDATION_FAILED,
                    "사용자 이메일이 일치하지 않습니다. 요청이메일: " + requestDto.getUserEmail() + ", 실제이메일: " + user.getEmail());
        }


        if (requestDto.getPaidAmount() <= 0) {
            throw new NotificationException(NotificationErrorCode.INVALID_PAYMENT_AMOUNT,
                    "결제 금액은 0보다 커야 합니다. 금액: " + requestDto.getPaidAmount());
        }
    }










    private Notification createCardPayment(Faq order, Product user, CardNotificationRequestDto requestDto) {
        Instant start = Instant.now();
        try {
            log.info("카드 결제 처리 시작: 주문ID={}, 결제정보ID={}",
                    order.getId(), requestDto.getPaymentInfoId());


            NotificationInfo paymentInfo;
            try {
                paymentInfo = paymentInfoQueryService.getPaymentInfoEntity(user.getEmail(), requestDto.getPaymentInfoId());
                if (paymentInfo == null) {
                    throw new NotificationInfoNotFoundException("결제 정보 ID: " + requestDto.getPaymentInfoId() + "를 찾을 수 없습니다.");
                }
            } catch (NotificationException e) {
                throw e;
            } catch (Exception e) {
                throw new NotificationInfoNotFoundException("결제 정보 조회 중 오류가 발생했습니다.", e);
            }


            Map<String, Object> response;
            try {
                response = portOneApiClient.processCardPayment(paymentInfo, requestDto.getPaidAmount());
            } catch (NotificationException e) {
                throw e;
            } catch (Exception e) {
                throw new NotificationApiException("카드 결제 요청 중 오류가 발생했습니다: " + e.getMessage());
